const room = msg.topic;
const action = msg.payload ? 'on' : 'off';
msg.url = `http://localhost:1880/api/lights/${room}/${action}`;
msg.method = 'POST';
msg.payload = {};
return msg;

// Fan out to check each service/device
// Output 1: MCP server check
// Output 2: Hue bridge check
// Output 3: CCU check
const mcp = { url: 'http://localhost:8000/', method: 'GET', requestTimeout: 3000 };
const hue = { url: 'http://hue-bridge/api/config', method: 'GET', requestTimeout: 3000 };
const ccu = { url: 'http://homematic-ccu/addons/xmlapi/version.cgi', method: 'GET', requestTimeout: 3000 };
return [mcp, hue, ccu];

// msg.payload is array of 3 responses [mcp, hue, ccu]
// Each has statusCode (200 = ok, or undefined/error)
const results = msg.payload || [];
const now = new Date().toLocaleTimeString('de-DE', {hour:'2-digit', minute:'2-digit', second:'2-digit'});

function check(resp, i) {
    if (resp && resp.statusCode && resp.statusCode >= 200 && resp.statusCode < 400) {
        return { status: 'online', code: resp.statusCode };
    }
    return { status: 'offline', code: resp ? resp.statusCode || 'err' : 'err' };
}

// Node-RED is always online if this flow is running
const nodered = { status: 'online' };
const mcp = check(results[0], 0);
const hue = check(results[1], 1);
const ccu = check(results[2], 2);

msg.payload = {
    timestamp: now,
    services: {
        nodered: nodered,
        mcp: mcp
    },
    devices: {
        hue: hue,
        ccu: ccu
    }
};
return msg;

// Save HTTP req/res for later response, then fan out to CCU + Hue
flow.set('_sync_req', msg.req);
flow.set('_sync_res', msg.res);
const hueKey = global.get("hue_api_key") || env.get("HUE_API_KEY") || "";
if (!hueKey) { node.warn("HUE_API_KEY not set — Hue sync will fail"); }
return [
    {payload:'', topic:'ccu'},
    {payload:'', topic:'hue', url:'http://hue-bridge/api/' + hueKey + '/lights'}
];

const xml = msg.payload;
if (!xml || msg.statusCode !== 200) { msg.payload = []; msg.topic = 'ccu'; return msg; }
const devices = [];
const re = /<device\s+name='([^']+)'\s+ise_id='([^']+)'\s+unreach='([^']*)'/g;
let m;
const map = {
    'HM-CC-RT-DN':  {c:'Thermostat',v:'heating',  cap:'sensor,actor',t:'thermostat'},
    'HmIP-STHD':    {c:'Thermostat',v:'heating',  cap:'sensor,actor',t:'thermostat'},
    'HM-LC-Dim':    {c:'Light',     v:'electrical',cap:'actor',       t:'dimmer'},
    'HM-LC-Sw':     {c:'Switch',    v:'electrical',cap:'actor',       t:'switch'},
    'HmIP-BSM':     {c:'Switch',    v:'electrical',cap:'sensor,actor',t:'switch'},
    'HmIP-FSM':     {c:'Switch',    v:'electrical',cap:'sensor,actor',t:'switch'},
    'HM-LC-Bl':     {c:'Actor',     v:'network',   cap:'actor',       t:'shutter'},
    'HM-PB-2':      {c:'Controller',v:'network',   cap:'controller',  t:'button'},
    'HmIP-BRC2':    {c:'Controller',v:'network',   cap:'controller',  t:'button'},
    'HMIP-WRC2':    {c:'Controller',v:'network',   cap:'controller',  t:'button'},
    'HM-Sec-SC':    {c:'Sensor',    v:'network',   cap:'sensor',      t:'contact'},
    'HM-Sen-MDIR':  {c:'Sensor',    v:'network',   cap:'sensor',      t:'motion'},
    'HM-WDS100':    {c:'Sensor',    v:'network',   cap:'sensor',      t:'weather'},
    'HmIP-SWSD':    {c:'Sensor',    v:'network',   cap:'sensor',      t:'smoke'},
    'HmIP-ASIR':    {c:'Actor',     v:'network',   cap:'actor',       t:'siren'},
    'HM-ES-PMSw':   {c:'Switch',    v:'electrical',cap:'sensor,actor',t:'meter'},
    'HM-OU-CF':     {c:'Actor',     v:'network',   cap:'actor',       t:'chime'},
    'HM-SCI-3':     {c:'Sensor',    v:'network',   cap:'sensor',      t:'contact'},
};
const skip = ['VIR-','HM-RCV-50','HmIP-RCV-','HmIP-CCU3','Living'];
while ((m = re.exec(xml)) !== null) {
    const name = m[1], ise = m[2];
    if (skip.some(p => name.startsWith(p))) continue;
    const parts = name.split(' ');
    const model = parts[0] || '', serial = parts[1] || '';
    let mapped = null;
    for (const pfx of Object.keys(map)) { if (model.startsWith(pfx)) { mapped = map[pfx]; break; } }
    if (!mapped) continue;
    devices.push({name,protocol:'homematic',address:serial,dhc_class:mapped.c,design_view:mapped.v,capability:mapped.cap,type:mapped.t,model,manufacturer:'eQ-3',ccu_ise_id:ise,hue_unique_id:null});
}
msg.payload = devices; msg.topic = 'ccu'; return msg;

const lights = msg.payload;
if (!lights || typeof lights !== 'object' || msg.statusCode !== 200) { msg.payload = []; msg.topic = 'hue'; return msg; }
const mfr = {'LTG002':'Philips','LWA011':'Philips','LWE002':'Philips','SP 240':'Innr','RS 241 T':'Innr'};
const tm = {'Dimmable light':{c:'Light',t:'light'},'Color temperature light':{c:'Light',t:'light'},'Extended color light':{c:'Light',t:'light'},'On/Off plug-in unit':{c:'Socket',t:'plug'}};
const devices = [];
for (const [id, l] of Object.entries(lights)) {
    const mapped = tm[l.type] || {c:'Light',t:'light'};
    devices.push({name:'hue-'+l.name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),protocol:'hue',address:id,dhc_class:mapped.c,design_view:'electrical',capability:'actor',type:mapped.t,model:l.modelid||'',manufacturer:mfr[l.modelid]||'Unknown',ccu_ise_id:null,hue_unique_id:l.uniqueid||null});
}
msg.payload = devices; msg.topic = 'hue'; return msg;

const ccu = msg.payload.ccu || [];
const hue = msg.payload.hue || [];
const all = [...ccu, ...hue];
const esc = v => v ? v.replace(/'/g,"''") : '';
const stmts = all.map(d =>
    `INSERT OR REPLACE INTO device (name,protocol,address,type,dhc_class,design_view,capability,model,manufacturer,ccu_ise_id,hue_unique_id,last_seen) VALUES ('${esc(d.name)}','${esc(d.protocol)}','${esc(d.address)}','${esc(d.type)}','${esc(d.dhc_class)}','${esc(d.design_view)}','${esc(d.capability)}','${esc(d.model)}','${esc(d.manufacturer)}',${d.ccu_ise_id?"'"+esc(d.ccu_ise_id)+"'":'NULL'},${d.hue_unique_id?"'"+esc(d.hue_unique_id)+"'":'NULL'},datetime('now'))`
);
msg.topic = stmts.join(";\n");
msg._counts = {ccu:ccu.length, hue:hue.length, total:all.length};
return msg;

// Restore HTTP req/res and build response
msg.req = flow.get('_sync_req');
msg.res = flow.get('_sync_res');
msg.payload = {status:'ok', synced: msg._counts || {ccu:0, hue:0, total:0}};
return msg;

// Read digitalhome.edge.config.cache and store keys in global context
// fs module is loaded via the node's "libs" config
const cfgPath = '/config/dhe.config.cache';
try {
    const cfg = JSON.parse(fs.readFileSync(cfgPath, 'utf8'));
    const hueKey = (cfg.devices && cfg.devices['hue-bridge'] && cfg.devices['hue-bridge'].api_key) || '';
    global.set('hue_api_key', hueKey);
    global.set('edge_config', cfg);
    node.log('Config loaded: hue_api_key=' + (hueKey ? 'set' : 'empty'));
    return {payload: {status: 'config loaded', hue_key_set: !!hueKey}};
} catch(e) {
    node.error('Failed to load config: ' + e.message);
    return {payload: {status: 'config load failed', error: e.message}};
}

const p = msg.payload || {};
const state = p.state || 'boot';
let statusText = ({
    boot:              'Starting…',
    unlinked:          'Reaching digitalhome.cloud…',
    awaiting_approval: 'Waiting for your approval on your phone…',
    linked:            'Linked ✓',
    denied:            'Pairing denied. Tap Restart to try again.',
    error:             p.error || 'Something went wrong. Tap Restart.'
})[state] || state;
if (state === 'linked') {
    statusText = p.home_id
        ? `Linked to ${p.home_id} ✓`
        : 'Registered ✓ — waiting to be linked to a home in the Portal (My Edges).';
}
msg.payload = { ...p, status_text: statusText };
return msg;

const index = global.get('aboxIndex') || null;
if (!index) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'aboxIndex missing' });
    const obs = (msg.payload && msg.payload.observations) || [];
    const unmapped = obs.map((o) => ({
        source: msg.payload && msg.payload.source,
        device_id: msg.payload && msg.payload.device_id,
        field: o && o.field,
        value: o && o.value,
        reason: 'abox_not_loaded'
    }));
    return [null, unmapped.map((u) => ({ payload: u, topic: 'unmapped' }))];
}

const p = msg.payload || {};
const src = p.source;
const devId = p.device_id;
const ts = p.ts ? new Date(p.ts).toISOString() : new Date().toISOString();
const observations = Array.isArray(p.observations) ? p.observations : [];
const homeId = p.home_id || global.get('homeId') || 'unknown';

const CONTEXT = 'https://schema.digitalhome.cloud/cbox/v0/context.jsonld';

const coerce = (raw, kind) => {
    switch (kind) {
        case 'byte-to-percent':
            return typeof raw === 'number' ? Math.round(raw * 10000 / 254) / 100 : raw;
        case 'unit-to-percent':
            return typeof raw === 'number' ? Math.round(raw * 10000) / 100 : raw;
        case 'mired-to-kelvin':
            return typeof raw === 'number' && raw > 0 ? Math.round(1000000 / raw) : raw;
        case 'centi-to-unit':
            return typeof raw === 'number' ? raw / 100 : raw;
        case 'hue-lightlevel-to-lux':
            return typeof raw === 'number' ? Math.round(Math.pow(10, (raw - 1) / 10000) * 100) / 100 : raw;
        case 'milli-to-unit':
            return typeof raw === 'number' ? raw / 1000 : raw;
        case 'wh-to-kwh':
            return typeof raw === 'number' ? raw / 1000 : raw;
        case 'invert-boolean':
            return typeof raw === 'boolean' ? !raw : (raw ? false : true);
        default:
            return raw;
    }
};

const uuidV4 = () => {
    const b = new Uint8Array(16);
    for (let i = 0; i < 16; i++) b[i] = Math.floor(Math.random() * 256);
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    const h = [...b].map((x) => x.toString(16).padStart(2, '0')).join('');
    return h.slice(0, 8) + '-' + h.slice(8, 12) + '-' + h.slice(12, 16) + '-' + h.slice(16, 20) + '-' + h.slice(20);
};

const mapped = [];
const unmapped = [];

for (const obs of observations) {
    if (!obs || obs.field == null) {
        unmapped.push({ source: src, device_id: devId, ts, field: obs && obs.field, value: obs && obs.value, reason: 'malformed_observation' });
        continue;
    }
    const key = src + '/' + obs.field;
    const entry = index.sourceMap[key];
    if (!entry) {
        unmapped.push({ source: src, device_id: devId, ts, field: obs.field, value: obs.value, reason: 'unknown_source_field' });
        continue;
    }
    const capMeta = index.capability[entry.capability];
    if (!capMeta) {
        unmapped.push({ source: src, device_id: devId, ts, field: obs.field, value: obs.value, reason: 'missing_capability', capability: entry.capability });
        continue;
    }
    const value = entry.coerce ? coerce(obs.value, entry.coerce) : obs.value;
    const fragment = {
        '@context': CONTEXT,
        '@id': 'urn:dhe:point:' + uuidV4(),
        '@type': capMeta.brickClass,
        'dhc:capability': entry.capability,
        'dhc:value': value,
        'dhc:observedAt': ts,
        'dhc:source': 'urn:dhe:' + src,
        'dhc:pointOf': 'urn:dhe:device:' + src + ':' + devId,
        'dhc:homeId': homeId
    };
    if (capMeta.unit)      fragment['dhc:unit']      = capMeta.unit;
    if (capMeta.valueType) fragment['dhc:valueType'] = capMeta.valueType;
    mapped.push(fragment);
}

const counts = flow.get('aboxFilterCounts') || { mapped: 0, unmapped: 0 };
counts.mapped   += mapped.length;
counts.unmapped += unmapped.length;
flow.set('aboxFilterCounts', counts);
node.status({ fill: 'green', shape: 'dot', text: 'mapped ' + counts.mapped + ' / unmapped ' + counts.unmapped });

const outMapped = mapped.map((f) => ({ payload: f, topic: 'cbox' }));
const outUnmapped = unmapped.map((u) => ({ payload: u, topic: 'unmapped' }));

return [
    outMapped.length ? outMapped : null,
    outUnmapped.length ? outUnmapped : null
];

const allowed = new Set(['cbox', 'unmapped']);
const isRaw = /^raw\/[a-z0-9][a-z0-9/_-]*$/i.test(msg.topic || '');
const channel = (allowed.has(msg.topic) || isRaw) ? msg.topic : 'misc';
const d = new Date();
const yyyy = d.getUTCFullYear();
const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
const dd = String(d.getUTCDate()).padStart(2, '0');
msg.filename = `/timeseries/${channel}/${yyyy}-${mm}-${dd}.jsonl`;
msg.payload = JSON.stringify(msg.payload);
return msg;

// Build global.aboxIndex from /cbox/mappings/*.map.json (source -> T-BOX field maps).
// fs is enabled via the node's libs config. Replaces the old inline dhc:sourceMap
// scan of abox.jsonld: each integration now owns one self-contained mapping file.
const DIR = '/cbox/mappings';
let manifest;
try {
    manifest = JSON.parse(fs.readFileSync(DIR + '/mappings-manifest.json', 'utf8'));
} catch (e) {
    node.error('mappings-manifest.json unreadable: ' + e.message);
    node.status({ fill: 'red', shape: 'ring', text: 'no manifest' });
    return null;
}

const capability = {};
const sourceMap = {};
let capCount = 0, mapCount = 0;
const loaded = [];

for (const src of (manifest.sources || [])) {
    let doc;
    try {
        doc = JSON.parse(fs.readFileSync(DIR + '/' + src.file, 'utf8'));
    } catch (e) {
        node.warn('mapping ' + src.file + ' skipped: ' + e.message);
        continue;
    }
    const sourceKey = doc.source || src.source;
    const caps = doc.capabilities || {};
    for (const capName of Object.keys(caps)) {
        capability['dhc:capability/' + capName] = {
            brickClass: caps[capName].brickClass,
            valueType:  caps[capName].valueType,
            unit:       caps[capName].unit
        };
        capCount++;
    }
    const fields = doc.fields || {};
    for (const field of Object.keys(fields)) {
        const f = fields[field];
        sourceMap[sourceKey + '/' + field] = {
            capability: 'dhc:capability/' + f.capability,
            coerce:     f.coerce
        };
        mapCount++;
    }
    loaded.push(sourceKey);
}

const raw = JSON.stringify({ capability, sourceMap });
let hash = 5381;
for (let i = 0; i < raw.length; i++) hash = ((hash * 33) ^ raw.charCodeAt(i)) >>> 0;
const prev = global.get('aboxIndex');
if (prev && prev.hash === hash) {
    node.status({ fill: 'blue', shape: 'dot', text: 'unchanged (' + prev.counts.capability + ' cap / ' + prev.counts.sourceMap + ' map)' });
    return null;
}

global.set('aboxIndex', {
    capability, sourceMap, hash,
    counts: { capability: capCount, sourceMap: mapCount },
    sources: loaded,
    loadedAt: new Date().toISOString(),
    version: manifest.version || 'unknown'
});
node.status({ fill: 'green', shape: 'dot', text: 'loaded ' + capCount + ' cap / ' + mapCount + ' map [' + loaded.join(',') + ']' });
node.log('mappings reloaded: ' + capCount + ' capabilities, ' + mapCount + ' fields from ' + loaded.join(', '));
return null;

// Normalize a huemagic-emitted message to the shape the A-Box filter expects:
//   { source: 'hue', device_id, ts, observations: [{ field, value }] }
//
// Huemagic gives us msg.info.id (light/sensor id) and msg.payload usually
// contains state fields directly, or msg.state does. Different node types
// vary — cover the common cases.

const id = (msg.info && (msg.info.uniqueId || msg.info.id)) || msg.uniqueId || 'unknown';
const state = msg.state || (msg.payload && typeof msg.payload === 'object' ? msg.payload : null);
if (!state || typeof state !== 'object') {
    node.warn('hue message without state: ' + JSON.stringify(msg.payload).slice(0, 120));
    return null;
}

const observations = Object.keys(state)
    .filter((k) => !/^last(updated|announced)$/.test(k))
    .filter((k) => state[k] !== null && state[k] !== undefined)
    .map((field) => ({ field, value: state[field] }));

if (!observations.length) return null;

msg.payload = {
    source: 'hue',
    device_id: String(id),
    ts: Date.now(),
    observations
};
return msg;

// Normalize a ccu-value message to the shape the A-Box filter expects.
// ccu-value emits one message per datapoint change:
//   msg.payload = value, msg.datapointName = 'TEMPERATURE',
//   msg.device = '<serial>', msg.channel = 1, msg.ts = <ms>

const field = msg.datapointName || msg.datapoint || (msg.topic && msg.topic.split('.').pop());
const devId = msg.device || msg.deviceName || msg.address || 'unknown';
const channel = msg.channel != null ? ':' + msg.channel : '';
const deviceId = devId + channel;

if (field == null) {
    node.warn('ccu message without datapoint field');
    return null;
}

msg.payload = {
    source: 'ccu',
    device_id: deviceId,
    ts: msg.ts || Date.now(),
    observations: [{ field, value: msg.payload }]
};
return msg;

const r = msg.payload || {};
if (!r.access_token) {
    const emsg = (r.msg || r.error || ('auth failed (code '+(r.code||'?')+')'));
    global.set('solar_link_state', { state:'error', message:emsg, email:msg._solar_email });
    node.status({fill:'red',shape:'ring',text:'auth failed'});
    return [ null, { payload:{state:'error',message:emsg} }, { payload:'✗ Connection failed: '+emsg } ];
}
const ttl=(typeof r.expires_in==='number'?r.expires_in:5184000)*1000;
const store={access_token:r.access_token,refresh_token:r.refresh_token||null,expires_at:Date.now()+ttl,uid:r.uid||null,email:msg._solar_email};
try{ fs.writeFileSync('/secrets/solarman-token.json',JSON.stringify(store),{mode:0o600}); }catch(e){ node.error('token store write failed: '+e.message); }
global.set('solarman_token',{bearer:r.access_token,exp:store.expires_at,refresh:store.refresh_token});
global.set('solar_link_state',{state:'linked',email:msg._solar_email});
node.status({fill:'green',shape:'dot',text:'linked ('+msg._solar_email+')'});
return [ {payload:{}}, {payload:{state:'linked'}}, { payload:'✓ Connected to Solarman' } ];

const t = global.get('solarman_token');
const cfg = global.get('solar_cfg') || {};
if (!t || !t.bearer) { node.warn('station list: no token yet'); return null; }
const base = cfg.base_url || 'https://globalapi.solarmanpv.com';
msg.method = 'POST';
msg.url = base + '/station/v1.0/list';
msg.headers = { 'Content-Type': 'application/json', 'Authorization': 'bearer ' + t.bearer };
msg.payload = { page: 1, size: 100 };
return msg;

const r = msg.payload || {};
const list = r.stationList || r.data || r.stations || [];
const ids = list.map((s) => s.id != null ? s.id : s.stationId).filter((x) => x != null);
global.set('solarman_stations', ids);
node.status({fill: ids.length ? 'green' : 'yellow', shape:'dot', text: ids.length + ' stations'});
if (!ids.length) node.warn('station list empty: ' + JSON.stringify(r).slice(0,200));
return null;

const t = global.get('solarman_token');
const cfg = global.get('solar_cfg') || {};
const stations = global.get('solarman_stations') || [];
if (!t || !t.bearer || Date.now() > t.exp) { node.warn('poll: token missing/expired'); node.status({fill:'yellow',shape:'ring',text:'token stale'}); return null; }
if (!stations.length) { node.warn('poll: no stations'); return null; }
const base = cfg.base_url || 'https://globalapi.solarmanpv.com';
const msgs = stations.map((id) => ({
    method: 'POST',
    url: base + '/station/v1.0/realTime',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'bearer ' + t.bearer },
    payload: { stationId: id },
    station_id: id
}));
node.status({fill:'blue',shape:'dot',text:'polling ' + msgs.length});
return [msgs];

// One realTime response -> (out1) raw bronze envelope, (out2) normalized silver record.
const r = msg.payload || {};
const stationId = msg.station_id;
const tsIso = new Date().toISOString();
const FIELDS = ['generationPower','usePower','gridPower','batteryPower','batterySoc','generationValue','generationTotal'];
const observations = FIELDS
    .filter((f) => r[f] !== undefined && r[f] !== null)
    .map((f) => ({ field: f, value: r[f] }));

global.set('solar_latest', { station_id: stationId, ts: tsIso, data: r, observations });

const rawMsg = { payload: { ts: tsIso, source: 'solarman', endpoint: '/station/v1.0/realTime', station_id: stationId, http_status: msg.statusCode || 200, response: r }, topic: 'raw/solarman' };
const normMsg = { payload: { source: 'solarman', device_id: String(stationId), ts: Date.now(), observations } };
node.status({fill:'green',shape:'dot',text: observations.length + ' obs @ ' + stationId});
return [rawMsg, normMsg];

// Manual/nightly history backfill: daily totals for the last 30 days per station.
const t = global.get('solarman_token');
const cfg = global.get('solar_cfg') || {};
const stations = global.get('solarman_stations') || [];
if (!t || !t.bearer) { node.warn('history: no token'); return null; }
const base = cfg.base_url || 'https://globalapi.solarmanpv.com';
const end = new Date();
const start = new Date(end.getTime() - 30 * 86400000);
const fmt = (d) => d.toISOString().slice(0, 10);
const msgs = stations.map((id) => ({
    method: 'POST',
    url: base + '/station/v1.0/history',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'bearer ' + t.bearer },
    payload: { stationId: id, timeType: 2, startTime: fmt(start), endTime: fmt(end) },
    station_id: id
}));
return [msgs];

const r = msg.payload || {};
msg.payload = { ts: new Date().toISOString(), source: 'solarman', endpoint: '/station/v1.0/history', station_id: msg.station_id, http_status: msg.statusCode || 200, response: r };
msg.topic = 'raw/solarman/history';
return msg;

const s = global.get('solar_link_state') || {state:'unknown'};
const latest = global.get('solar_latest');
msg.statusCode = (s.state==='linked') ? 200 : 503;
msg.payload = latest && latest.station_id ? latest : { state: s.state, note: 'linked but no reading yet' };
return msg;

const code = msg.statusCode || (msg.error && msg.error.statusCode);
node.warn('solarman http error: ' + ((msg.error && msg.error.message) || code));
if (code === 401 || code === 403) {
    global.set('solarman_token', null);
    global.set('solar_link_state', { state: 'unlinked', message: 'session expired — please reconnect' });
    try { fs.unlinkSync('/secrets/solarman-token.json'); } catch(e) {}
    return { payload: {} };
}
return null;

if (msg.topic==='email') flow.set('sol_email', String(msg.payload||'').trim());
else if (msg.topic==='password') flow.set('sol_pass', String(msg.payload||''));
else if (msg.topic==='show') flow.set('sol_show', !!msg.payload);
const show=flow.get('sol_show'); const pw=flow.get('sol_pass')||'';
return { payload: (show && pw) ? ('shown: '+pw) : '' };

if (msg.topic==='disconnect' || msg.payload==='disconnect') { msg.payload={action:'disconnect'}; }
else { msg.payload={action:'connect', email:flow.get('sol_email')||'', password:flow.get('sol_pass')||''}; }
return msg;

// On boot, load /secrets/solarman-token.json (written by the dashboard login).
// If a valid token is present -> LINKED and start polling; else UNLINKED.
let cfg = {};
try { cfg = (JSON.parse(fs.readFileSync('/config/dhe.config.cache','utf8')).solar) || {}; } catch(e) {}
global.set('solar_cfg', { base_url: cfg.base_url || 'https://globalapi.solarmanpv.com', poll_interval_s: cfg.poll_interval_s || 300 });
let store = null;
try { store = JSON.parse(fs.readFileSync('/secrets/solarman-token.json','utf8')); } catch(e) {}
if (store && store.access_token && (!store.expires_at || Date.now() < store.expires_at)) {
    global.set('solarman_token', { bearer: store.access_token, exp: store.expires_at || (Date.now()+3600000), refresh: store.refresh_token });
    global.set('solar_link_state', { state: 'linked', email: store.email || '' });
    node.status({fill:'green',shape:'dot',text:'linked ('+(store.email||'')+')'});
    return { payload: {} };   // -> trigger station discovery
}
global.set('solar_link_state', { state: 'unlinked' });
node.status({fill:'grey',shape:'ring',text:'unlinked — awaiting dashboard login'});
return null;

const body = msg.payload || {};
if (body.action === 'disconnect') {
    try { fs.unlinkSync('/secrets/solarman-token.json'); } catch(e) {}
    global.set('solarman_token', null);
    global.set('solar_link_state', { state:'unlinked' });
    node.status({fill:'grey',shape:'ring',text:'disconnected'});
    return [ null, { payload:'Disconnected from Solarman' } ];
}
const email=(body.email||'').trim(); const password=body.password||'';
if(!email||!password){ global.set('solar_link_state',{state:'error',message:'email and password required'}); return [ null, { payload:'⚠ Enter both email and password' } ]; }
let cfg={}; try{ cfg=(JSON.parse(fs.readFileSync('/config/dhe.config.cache','utf8')).solar)||{}; }catch(e){}
const base=cfg.base_url||'https://globalapi.solarmanpv.com'; const appId=cfg.app_id;
let appSecret=''; try{ appSecret=fs.readFileSync('/secrets/solarman-app-secret','utf8').trim(); }catch(e){}
if(!appId||!appSecret){ global.set('solar_link_state',{state:'error',message:'app_id/app-secret not configured'}); return [ null, { payload:'✗ Edge missing app_id / app-secret' } ]; }
global.set('solar_cfg',{base_url:base,poll_interval_s:cfg.poll_interval_s||300});
global.set('solar_link_state',{state:'connecting',email:email});
const hash=crypto.createHash('sha256').update(password).digest('hex');
msg._solar_email=email; msg.method='POST';
msg.url=base+'/account/v1.0/token?appId='+encodeURIComponent(appId)+'&language=en';
msg.headers={'Content-Type':'application/json'};
msg.payload={appSecret:appSecret,email:email,password:hash};
node.status({fill:'blue',shape:'dot',text:'authenticating '+email});
return [ msg, { payload:'Connecting to Solarman… ('+email+')' } ];

const s = global.get('solar_link_state') || { state:'unlinked' };
const tok = global.get('solarman_token');
const latest = global.get('solar_latest');
const stations = (global.get('solarman_stations') || []).length;
const badge = { unlinked:'Not connected', connecting:'Connecting…', linked:'Connected ✓', error:('Error — '+(s.message||'connect failed')) }[s.state] || s.state;
msg.payload = {
    state: s.state,
    badge,
    email: s.email || '—',
    stations,
    last_poll_h: latest && latest.ts ? latest.ts : 'waiting for first poll…',
    token_expires_h: tok && tok.exp ? new Date(tok.exp).toISOString().slice(0,16).replace('T',' ') : '—',
    summary: badge + (s.state==='linked' ? ('  ('+(s.email||'')+', '+stations+' station'+(stations===1?'':'s')+')') : '')
};
return msg;

const buf = global.get('recent_mapped') || [];
buf.unshift(msg.payload); if (buf.length > 20) buf.length = 20;
global.set('recent_mapped', buf); return null;

const buf = global.get('recent_unmapped') || [];
buf.unshift(msg.payload); if (buf.length > 20) buf.length = 20;
global.set('recent_unmapped', buf); return null;

const c = flow.get('aboxFilterCounts', 'sf-abox-filter') || { mapped: 0, unmapped: 0 };
const idx = global.get('aboxIndex') || {};
msg.payload = { mapped: c.mapped, unmapped: c.unmapped, sources: (idx.sources||[]).join(', '),
                capabilities: idx.counts && idx.counts.capability, fields: idx.counts && idx.counts.sourceMap };
return msg;

let cfg = {};
try { cfg = JSON.parse(fs.readFileSync('/config/dhe.config.cache','utf8')); } catch(e) { cfg = {error:e.message}; }
const RED = new Set(['api_key','credential_secret','auth_token','admin_password','http_password','password','email']);
const redact = (o) => Array.isArray(o) ? o.map(redact)
    : (o && typeof o === 'object') ? Object.fromEntries(Object.entries(o).map(([k,v]) => [k, RED.has(k) && v ? '***' : redact(v)]))
    : o;
msg.payload = redact(cfg); return msg;

const idx = global.get('aboxIndex') || {};
const sm = idx.sourceMap || {};
const rows = Object.keys(sm).map(k => ({ key: k, capability: (sm[k].capability||'').replace('dhc:capability/',''),
    brick: ((idx.capability||{})[sm[k].capability]||{}).brickClass, coerce: sm[k].coerce || '' }));
msg.payload = rows; return msg;

function rd(p){ try { return JSON.parse(fs.readFileSync(p,'utf8')); } catch(e){ return null; } }
const hue=rd('/secrets/hue.json'); const ccu=rd('/secrets/ccu.json');
if(hue && hue.ip){ global.set('hue_ip',hue.ip); if(hue.api_key) global.set('hue_api_key',hue.api_key);
    global.set('hue_link',{state:'linked',ip:hue.ip,bridgeid:hue.bridgeid}); }
else global.set('hue_link',{state:'unlinked'});
if(ccu && ccu.ip){ global.set('ccu_ip',ccu.ip); if(ccu.token) global.set('ccu_token',ccu.token);
    if(ccu.user) global.set('ccu_user',ccu.user); if(ccu.pass) global.set('ccu_pass',ccu.pass);
    global.set('ccu_link',{state:'linked',ip:ccu.ip,version:ccu.version,auth:ccu.token?'token':(ccu.user?'session':'open')}); }
else global.set('ccu_link',{state:'unlinked'});
node.status({fill:'blue',shape:'dot',text:'hue '+(hue?'ok':'-')+' / ccu '+(ccu?'ok':'-')});
return null;

function line(link,latest){ const s=link&&link.state||'unlinked';
  const badge={unlinked:'Not connected',linked:'Connected ✓'}[s]||s;
  if(s==='linked'){ const t=(latest&&latest.ts)?(' · last '+latest.ts.slice(11,19)+'Z'):' · waiting for poll…';
    return badge+' @ '+(link.ip||'?')+t; }
  return badge+' — Scan, confirm IP, then Connect'; }
const ccu=line(global.get('ccu_link'), global.get('ccu_latest'));
const hue=line(global.get('hue_link'), global.get('hue_latest'));
return [ {payload:ccu}, {payload:hue} ];

return (async()=>{
  let base=flow.get('scan_subnet');
  if(!base){ const ifs=os.networkInterfaces(); const cands=[];
    for(const nm of Object.keys(ifs)){ if(/^(lo|docker|veth|br-|virbr|tun|tap)/i.test(nm)) continue;
      for(const a of ifs[nm]){ if(a.family!=='IPv4'||a.internal) continue;
        if(/^192\.168\./.test(a.address)) cands.unshift(a.address);
        else if(/^10\./.test(a.address)) cands.push(a.address);
        else if(/^172\.(1[6-9]|2\d|3[01])\./.test(a.address) && !/^172\.(17|18)\./.test(a.address)) cands.push(a.address);
      } }
    if(cands.length) base=cands[0].split('.').slice(0,3).join('.');
  }
  if(!base){ node.status({fill:'red',shape:'ring',text:'no subnet'}); return [ {payload:'could not determine subnet — set Subnet manually'}, {payload:'⚠ Scan: subnet not found'} ]; }
  node.status({fill:'blue',shape:'dot',text:'scanning '+base+'.0/24'});
  const get=(url,tmo)=>new Promise((resolve)=>{ try{ const req=http.get(url,{timeout:tmo||1200},(res)=>{
      let b=''; res.on('data',c=>b+=c); res.on('end',()=>resolve({status:res.statusCode,body:b})); });
    req.on('timeout',()=>{req.destroy();resolve(null);}); req.on('error',()=>resolve(null)); }catch(e){resolve(null);} });
  const probe=async(ip)=>{ const r=await get('http://'+ip+'/addons/xmlapi/version.cgi',1200);
    if(r && r.status===200){ return {ip, version:((r.body.match(/>([0-9.]+)</)||[])[1]||'?')}; } return null; };
  const ips=[]; for(let i=1;i<=254;i++) ips.push(base+'.'+i);
  const res=(await Promise.allSettled(ips.map(probe))).map(r=>r.value).filter(Boolean);
  global.set('ccu_candidates',res); if(res.length) flow.set('ccu_ip_pending',res[0].ip);
  node.status({fill:res.length?'green':'yellow',shape:'dot',text:res.length+' CCU found'});
  const line=res.length? res.map(c=>c.ip).join(', ') : 'none found on '+base+'.0/24';
  return [ {payload:'Found: '+line}, {payload:'CCU scan: '+res.length+' found'} ];
})();

if(msg.topic==='token'){ flow.set('ccu_token_pending', String(msg.payload||'').trim()); return null; }
if(msg.topic==='subnet'){ flow.set('scan_subnet', String(msg.payload||'').trim().replace(/\.$/,'')||null); return null; }
if(msg.topic==='ip') flow.set('ccu_ip_pending', String(msg.payload||'').trim());
else if(msg.topic==='user') flow.set('ccu_user_pending', String(msg.payload||''));
else if(msg.topic==='pass') flow.set('ccu_pass_pending', String(msg.payload||''));
return null;

return (async()=>{
  const ip=(flow.get('ccu_ip_pending')||global.get('ccu_ip')||'').trim();
  if(!ip) return {payload:'⚠ Enter the CCU IP first'};
  const token=(flow.get('ccu_token_pending')||global.get('ccu_token')||'').trim();
  const user=(flow.get('ccu_user_pending')||'').trim(); const pass=flow.get('ccu_pass_pending')||'';
  const reqJson=(ip,method,path,body,tmo)=>new Promise((resolve)=>{ try{
    const data=body?JSON.stringify(body):null;
    const opts={hostname:ip,port:80,path:path,method:method,timeout:tmo||5000,headers:{}};
    if(data){ opts.headers['Content-Type']='application/json'; opts.headers['Content-Length']=Buffer.byteLength(data); }
    const req=http.request(opts,(res)=>{ let b=''; res.on('data',c=>b+=c); res.on('end',()=>resolve({status:res.statusCode,body:b})); });
    req.on('timeout',()=>{req.destroy();resolve(null);}); req.on('error',()=>resolve(null));
    if(data) req.write(data); req.end();
  }catch(e){ resolve(null); } });
  const ccuLogin=async(ip,user,pass)=>{ const r=await reqJson(ip,'POST','/api/homematic.cgi',{method:'Session.login',params:{username:user,password:pass},id:1},5000);
    if(!r) return {err:'unreachable'}; let j; try{ j=JSON.parse(r.body); }catch(e){ return {err:'bad response'}; }
    if(j && j.result) return {sid:j.result}; return {err:(j&&j.error&&j.error.message)||'login failed'}; };
  const ver=await reqJson(ip,'GET','/addons/xmlapi/version.cgi',null,4000);
  if(!ver) return {payload:'✗ No CCU reachable at '+ip};
  if(ver.status===404) return {payload:'✗ CCU at '+ip+': XML-API addon not installed'};
  const version=((ver.body.match(/>([0-9.]+)</)||[])[1]||'?');
  let auth='open';
  if(token){
    const st=await reqJson(ip,'GET','/addons/xmlapi/statelist.cgi?sid='+encodeURIComponent(token),null,5000);
    if(!st || /not_authenticated/.test(st.body||'') || !/<device/.test(st.body||'')) return {payload:'✗ CCU token rejected'};
    auth='token'; global.set('ccu_token',token);
  } else if(user && pass){ const lg=await ccuLogin(ip,user,pass); if(lg.err) return {payload:'✗ CCU login failed: '+lg.err}; global.set('ccu_sid',lg.sid); auth='session'; }
  else { const st=await reqJson(ip,'GET','/addons/xmlapi/statelist.cgi',null,4000);
    if(st && /not_authenticated/.test(st.body||'')) return {payload:'⚠ CCU needs an API token (or username+password) — add one and Connect'}; }
  fs.writeFileSync('/secrets/ccu.json',JSON.stringify({ip,version,token:token||'',user:token?'':user,pass:token?'':pass}),{mode:0o600});
  global.set('ccu_ip',ip); global.set('ccu_user',user); global.set('ccu_pass',pass);
  global.set('ccu_link',{state:'linked',ip,version,auth});
  node.status({fill:'green',shape:'dot',text:'CCU '+ip+' ('+auth+')'});
  node.send([ {payload:'✓ CCU connected ('+ip+', v'+version+', '+auth+')'}, {payload:{}} ]); return null;
})();

