    const funcArr=[...(funcs&&funcs.body||'').matchAll(/<function[^>]*name=['"]([^'"]+)['"][^>]*>([\s\S]*?)<\/function>/g)].map(m=>({name:m[1],channels:(m[2].match(/<channel/g)||[]).length}));
    const devArr=[...(devs.body||'').matchAll(/<device[^>]*name=['"]([^'"]+)['"][^>]*address=['"]([^'"]*)['"][^>]*device_type=['"]([^'"]*)['"]/g)].map(m=>({name:m[1],address:m[2],type:m[3]}));
    const cfg={source:'ccu',ip,fetched_at:new Date().toISOString(),rooms:roomArr,functions:funcArr,devices:devArr,raw:{roomlist:rooms&&rooms.body,functionlist:funcs&&funcs.body,devicelist:devs.body}};
    try{ fs.writeFileSync('/cbox/discovered/ccu.json',JSON.stringify(cfg,null,1)); }catch(e){ return done(false,'write failed: '+e.message); }
    const sum={rooms:roomArr.length,functions:funcArr.length,devices:devArr.length,fetched_at:cfg.fetched_at,room_names:roomArr.map(r=>r.name).slice(0,20)};
    global.set('ccu_config',sum);
    return done(true,'CCU config updated',sum);
  }
  if(source==='hue'){
    const ip=global.get('hue_ip'); const key=global.get('hue_api_key');
    if(!ip||!key) return done(false,'Hue not connected');
    const full=await get(ip,'/api/'+key,9000);
    if(!full) return done(false,'Hue unreachable');
    let j; try{ j=JSON.parse(full.body); }catch(e){ return done(false,'bad Hue response'); }
    if(Array.isArray(j)&&j[0]&&j[0].error) return done(false,'Hue error: '+(j[0].error.description||''));
    const groups=j.groups||{}; const rooms=Object.keys(groups).filter(k=>groups[k].type==='Room'||groups[k].type==='Zone').map(k=>({name:groups[k].name,type:groups[k].type,lights:(groups[k].lights||[]).length}));
    const summary={lights:Object.keys(j.lights||{}).length,rooms:rooms.length,scenes:Object.keys(j.scenes||{}).length,sensors:Object.keys(j.sensors||{}).length};
    const cfg=Object.assign({source:'hue',ip,fetched_at:new Date().toISOString(),room_list:rooms,raw:j},summary);
    try{ fs.writeFileSync('/cbox/discovered/hue.json',JSON.stringify(cfg,null,1)); }catch(e){ return done(false,'write failed: '+e.message); }
    const sum=Object.assign({fetched_at:cfg.fetched_at,room_names:rooms.map(r=>r.name).slice(0,20)},summary);
    global.set('hue_config',sum);
    return done(true,'Hue config updated',sum);
  }
  return done(false,'source must be ccu or hue');
})();
